describe('Loading States Accessibility', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.injectAxe();
  });

  it('should announce loading state to screen readers when data is being fetched', () => {
    cy.get('[data-testid="load-button"]').click();

    cy.get('[role="status"]').should('exist');
    cy.get('[role="status"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[role="status"]').should('contain', 'Loading');

    cy.get('[role="status"]').should('have.attr', 'aria-busy', 'true');

    cy.get('[data-testid="load-button"]').should('have.attr', 'aria-busy', 'true');
    cy.get('[data-testid="load-button"]').should('have.attr', 'disabled');

    cy.wait(2000);
    cy.get('[role="status"]').should('have.attr', 'aria-busy', 'false');
    cy.get('[role="status"]').should('contain', 'Loading complete');
  });

  it('should update aria-label dynamically during loading states', () => {
    cy.get('[data-testid="async-action"]').should('have.attr', 'aria-label', 'Fetch data');

    cy.get('[data-testid="async-action"]').click();

    cy.get('[data-testid="async-action"]').should('have.attr', 'aria-label', 'Loading data, please wait');
    cy.get('[data-testid="async-action"]').should('have.attr', 'aria-busy', 'true');

    cy.wait(1500);
    cy.get('[data-testid="async-action"]').should('have.attr', 'aria-label', 'Data loaded successfully');
    cy.get('[data-testid="async-action"]').should('have.attr', 'aria-busy', 'false');
  });

  it('should maintain focus management during loading state transitions', () => {
    cy.get('[data-testid="load-button"]').focus();
    cy.focused().should('have.attr', 'data-testid', 'load-button');

    cy.get('[data-testid="load-button"]').click();

    cy.focused().should('have.attr', 'data-testid', 'load-button');
    cy.get('[data-testid="load-button"]').should('have.attr', 'disabled');

    cy.wait(2000);
    cy.get('[data-testid="load-button"]').should('not.have.attr', 'disabled');
    cy.focused().should('have.attr', 'data-testid', 'load-button');
  });

  it('should provide loading progress information to assistive technology', () => {
    cy.get('[data-testid="progress-load"]').click();

    cy.get('[role="progressbar"]').should('exist');
    cy.get('[role="progressbar"]').should('have.attr', 'aria-valuenow');
    cy.get('[role="progressbar"]').should('have.attr', 'aria-valuemin', '0');
    cy.get('[role="progressbar"]').should('have.attr', 'aria-valuemax', '100');

    cy.get('[role="progressbar"]').invoke('attr', 'aria-valuenow').then((value) => {
      expect(parseInt(value)).to.be.greaterThan(0);
      expect(parseInt(value)).to.be.lessThanOrEqual(100);
    });

    cy.wait(2000);
    cy.get('[role="progressbar"]').should('have.attr', 'aria-valuenow', '100');
  });

  it('should handle error states with proper accessibility announcements', () => {
    cy.get('[data-testid="load-with-error"]').click();

    cy.get('[role="alert"]').should('exist');
    cy.get('[role="alert"]').should('have.attr', 'aria-live', 'assertive');
    cy.get('[role="alert"]').should('contain', 'Error');

    cy.get('[data-testid="load-with-error"]').should('have.attr', 'aria-busy', 'false');
    cy.get('[role="alert"]').should('have.attr', 'aria-atomic', 'true');
  });

  it('should pass axe accessibility checks during loading states', () => {
    cy.get('[data-testid="load-button"]').click();

    cy.checkA11y(null, {
      rules: {
        'aria-required-attr': { enabled: true },
        'aria-valid-attr-role': { enabled: true },
        'button-name': { enabled: true }
      }
    });

    cy.wait(2000);
    cy.checkA11y(null, {
      rules: {
        'aria-required-attr': { enabled: true },
        'aria-valid-attr-role': { enabled: true }
      }
    });
  });

  it('should announce loading completion with appropriate aria-live region', () => {
    cy.get('[data-testid="fetch-data"]').click();

    cy.get('[aria-live="polite"][aria-atomic="true"]').should('exist');

    cy.wait(1500);
    cy.get('[aria-live="polite"][aria-atomic="true"]').should('contain', 'Data loaded');

    cy.get('[data-testid="fetch-data"]').should('not.have.attr', 'aria-busy');
  });
});
